ADAPTER_SHA = 'cd76698ae0d4c74aa5e65b6389ee3f5785cfea0ff548c7013527c101e133857d'
ADAPTER_GZIP_B64 = ''


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))


def clean(value):
    if isinstance(value, dict): return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)): return [clean(v) for v in value]
    if hasattr(value, 'tolist'): return clean(value.tolist())
    if isinstance(value, float) and not math.isfinite(value): return None
    return value


def save(path, value):
    path = Path(path)
    if path.is_symlink(): raise RuntimeError('拒绝覆盖链接')
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + '.pending_' + str(os.getpid()))
    temporary.write_text(json.dumps(clean(value), ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    os.replace(temporary, path)


def sha(path):
    result = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for data in iter(lambda: stream.read(1024 * 1024), b''): result.update(data)
    return result.hexdigest()


def object_sha(value):
    return hashlib.sha256(json.dumps(clean(value), sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()).hexdigest()


def adapter():
    raw = gzip.decompress(base64.b64decode(ADAPTER_GZIP_B64))
    if hashlib.sha256(raw).hexdigest() != ADAPTER_SHA: raise RuntimeError('封存适配层哈希失败')
    tree = ast.parse(raw.decode('utf-8-sig'))
    tree.body = [node for node in tree.body if not (
        isinstance(node, ast.If) and isinstance(node.test, ast.Compare)
        and isinstance(node.test.left, ast.Name) and node.test.left.id == '__name__')]
    result = types.ModuleType('mechanism_frozen_adapter')
    result.__file__ = str(Path(__file__).resolve())
    sys.modules[result.__name__] = result
    exec(compile(tree, '<已封存的零训练适配层>', 'exec'), result.__dict__)
    result.PROJECT = PROJECT
    return result


def guard(job):
    if (Path(job['run_root']) / 'STOP_REQUESTED').exists(): raise TimeoutError('用户请求停止本轮')
    if time.monotonic() >= job['deadline']: raise TimeoutError('会话到时，已完成状态保留供续跑')


def normal_slots(control):
    # 五个普通运营时间段，每段六个状态；先跑六个覆盖点，再均衡补充。
    return [('passenger', i) for i in range(30)] if control == 'LQ' else [
        ('air_only' if i % 3 == 2 else 'passenger', i) for i in range(30)]


def slot_for(kind, ordinal):
    # 编号对应的时间段不依赖结果、等待长短或事后收益。
    available = [i for i in range(30) if (i % 3 == 2) == (kind == 'air_only')]
    return available[ordinal] if ordinal < len(available) else None


def pass_slots(control, pass_id):
    kinds = normal_slots(control)
    primary = {0, 2, 6, 14, 21, 29} if control == 'J3' else {0, 5, 10, 15, 20, 25}
    rest = [i for i in range(30) if i not in primary]
    picked = sorted(primary) if pass_id == 0 else rest[(pass_id - 1) * 12:pass_id * 12]
    return [kinds[i] for i in picked]


def sample_snapshot(d, base, m, job, env, obs, reservoirs, seen, kind, index):
    t = int(env.scenario.time)
    if not 40 <= t < 260: return
    band = min(4, (t - 40) // 44)
    key = (kind, band)
    seen[key] += 1
    quota = 6 if job['case']['task']['control'] == 'LQ' else (4 if kind == 'passenger' else 2)
    reservoir = reservoirs[key]
    rng = random.Random(SEED + band * 100003 + index * 31 + (0 if kind == 'passenger' else 17))
    selected = len(reservoir) if len(reservoir) < quota else rng.randrange(seen[key])
    if selected >= quota: return
    value = dict(env=base.clone_env(env), obs=obs.copy(), rng=d.rng_get(m), time=t,
                 kind=kind, offset=index, state_sha=d.object_sha(d.state_view(env)))
    if selected < len(reservoir):
        reservoir[selected]['env'].close()
        reservoir[selected] = value
    else: reservoir.append(value)


def planes_view(env):
    return sorted([dict(id=str(p.id), state=p.state.name, at=str(p.current_vertiport_id),
        target=str(getattr(p, 'target_vertiport_id', '')), passengers=sorted(map(str, p.passenger_ids)),
        remaining=float(getattr(p, 'remaining_time', 0) or 0), battery=float(p.battery_kwh))
        for p in env.scenario._all_evtols.values()], key=lambda x: x['id'])


def advance(d, base, m, job, private, env, obs, model, norm, controller,
            force_p=None, force_air=None, hook=None):
    """保留真实prepare/finish顺序，飞机合法集合必须在dispatch位置取得。"""
    guard(job)
    active = bool(env.scenario.waiting_decisions)
    pre = norm.normalize_obs(obs[None])
    passenger_probs = None; aircraft_probs = None
    if force_p is not None:
        if not active and int(force_p) != 0: raise RuntimeError('没有乘客时不能虚构乘客决策')
        passenger = int(force_p)
    elif not active: passenger = 0
    elif controller == 'READY': passenger = int(base.ready(env, m))
    else:
        selected, _, probabilities = model.policy.sample_passenger(m.torch.as_tensor(pre, device='cpu'), True)
        passenger = int(selected[0]); passenger_probs = probabilities[0].detach().cpu().tolist()
    if not 0 <= passenger < env.k: raise RuntimeError('非法乘客候选')
    raw = env.prepare_step(passenger)
    legal = [i for i, flag in enumerate(raw[env.schema.return_mask]) if flag > .5]
    if not env.joint or controller == 'READY': aircraft = -1
    else:
        pending = norm.normalize_obs(raw[None])
        pending[:, :env.schema.pack] = pre[:, :env.schema.pack]
        distribution = model.policy.return_distribution(m.torch.as_tensor(pending, device='cpu'),
            m.torch.as_tensor([passenger], device='cpu'))
        aircraft = int(distribution.probs.argmax(-1)[0])
        aircraft_probs = distribution.probs[0].detach().cpu().tolist()
    natural = aircraft
    if force_air is not None:
        if not env.joint: raise RuntimeError('单侧不拥有飞机覆盖权限')
        aircraft = int(force_air)
    if hook is not None and env.joint:
        chosen = hook(int(env.scenario.time), legal, natural)
        if chosen is not None: aircraft = int(chosen)
    if aircraft >= 0 and aircraft not in legal: raise RuntimeError('飞机覆盖不在真实合法集合')
    result, reward, done, info = env.finish_step(aircraft)
    return result, bool(done), dict(passenger=passenger, aircraft=aircraft, natural_aircraft=natural,
                                  legal=legal, active=active, passenger_probs=passenger_probs, aircraft_probs=aircraft_probs)


def causal_four(costs, applied, epsilon):
    c00, c10, c01, c11 = [costs[key] for key in ('00', '10', '01', '11')]
    return dict(single_a_gain=c00-c10, single_b_gain=c00-c01, pair_gain=c00-c11,
        interaction=c11-c10-c01+c00, pair_extra=min(c00, c10, c01)-c11,
        clean_pair=bool(applied),
        pair_required=bool(applied and c10 >= c00-epsilon and c01 >= c00-epsilon and c11 < c00-epsilon))


def heuristic_scores(env, m):
    """比较当前队列代理与已存在的READY规则；两者均不是最优值或新AI。"""
    if not env.scenario.waiting_decisions: return None
    s = env.scenario
    focal = s.persons.persons[s.waiting_decisions[0]]
    result = []
    for vid in m.CANDIDATES[env.k]:
        station = s.vertiports.vertiport_list[str(vid)]
        access = float(s.vehicles.estimate_travel_time(focal.origin_position, station.vertiport_position))
        distance = s.vertiports._calculate_distance(station.vertiport_position, s.vertiports.vertiport_list['2'].vertiport_position)
        flight = distance / 200. * 60.
        supply = [max(0., e.spec.battery_capacity_kwh-e.battery_kwh)/max(e.spec.charge_rate_kwh_per_min, 1e-9)
            for e in s.vertiports.evtols_at_vertiport.get(str(vid), [])
            if not e.passenger_ids and e.state.name in ('IDLE', 'CHARGING')]
        incoming = sum(str(getattr(p, 'origin_vertiport_id', '')) == str(vid) and p.state == 'enroute'
            and p.sub_state == 'to_vertiport' and max(0., float(p.current_timer or 0)) <= access
            for p in s.persons.persons.values())
        cycle = 2*flight+2*distance*.55/5.32
        ready_base = min(supply, default=flight+distance*.55/5.32)
        now_wait = ready_base+len(station.person_list)//4*cycle/max(1, len(supply))
        aligned_wait = ready_base+(len(station.person_list)+incoming)//4*cycle/max(1, len(supply))
        result.append(dict(station=str(vid), access=access, queue=len(station.person_list),
            committed_arrivals_by_access=incoming, current_score=access+now_wait+flight,
            ready_score=max(access, aligned_wait)+flight))
    return result


def person_tick(env, costs, timeline, boarded_at, start):
    """只积累已生成乘客的真实状态；记录的是一分钟观测，不伪造精确亚分钟时刻。"""
    s = env.scenario
    finished = set(map(str, s.finished_ids))
    queued = {str(pid) for v in s.vertiports.vertiport_list.values() for pid in v.person_list}
    for pid, p in s.persons.persons.items():
        pid = str(pid)
        if pid not in finished: costs[pid] += 1
        row = timeline.setdefault(pid, dict(born=int(p.spawn_time), queue_seen=None, board_seen=None,
            finish_seen=None, station=None))
        if getattr(p, 'origin_vertiport_id', None) is not None: row['station'] = str(p.origin_vertiport_id)
        if pid in queued and row['queue_seen'] is None: row['queue_seen'] = int(s.time)
        if p.sub_state == 'fly' and row['board_seen'] is None:
            row['board_seen'] = int(s.time)
            boarded_at[pid] = int(s.time)
        if pid in finished and row['finish_seen'] is None: row['finish_seen'] = int(s.time)


def rollout(d, base, m, job, private, template, obs, model, norm, controller, state_rng,
            plan=None, forecast=None, end_time=END_TIME, initial_controller=None):
    """完整后缀是事后条件评估；预测分支替换未揭示需求，绝不将真实未来输入选择器。"""
    guard(job)
    plan = dict(plan or {})
    d.rng_set(m, state_rng)
    env = base.clone_env(template)
    current = obs.copy()
    if forecast is not None: env.scenario.persons.file_data = copy.deepcopy(forecast)
    start = int(env.scenario.time)
    initial = set(map(str, env.scenario.persons.persons))
    focal = str(env.scenario.waiting_decisions[0]) if env.scenario.waiting_decisions else None
    total = 0; operating = 0; tail = 0; phases = Counter(); cohorts = Counter()
    individual = Counter(); timeline = {}; boarded = {}; points = {}; air_points = {}; departures = []
    b_record = dict(requested=plan.get('second_air'), triggered=False, changed=False, time=None)
    ticks = 0; first_post = None; first_air_post = None; first_details = None; cost_curve=[0]
    def second_hook(now, legal, natural):
        if b_record['requested'] is None or b_record['triggered']: return None
        delay = int(plan.get('second_delay', 1))
        if not start+delay <= now <= start+delay+10 or len(legal) <= 1 or b_record['requested'] not in legal: return None
        b_record.update(triggered=True, changed=natural != b_record['requested'], time=now,
                        legal=list(legal), natural=natural)
        return b_record['requested']
    try:
        with m.torch.no_grad():
            while env.scenario.time < end_time:
                guard(job)
                n, groups, comp = d.cost_tick(env, initial, focal)
                total += n; phases.update(comp); cohorts.update(groups)
                cost_curve.append(total)
                if env.scenario.time < env.scenario.passenger_generation_end_time: operating += n
                if d.tail_absorbing(env): tail += n
                person_tick(env, individual, timeline, boarded, start)
                before_planes = planes_view(env)
                step_controller = initial_controller if ticks == 0 and initial_controller is not None else controller
                current, done, detail = advance(d, base, m, job, private, env, current, model, norm, step_controller,
                    force_p=plan.get('p') if ticks == 0 else None,
                    force_air=plan.get('air') if ticks == 0 else None,
                    hook=second_hook if ticks > 0 else None)
                after_planes = planes_view(env)
                for before, after in zip(before_planes, after_planes):
                    if before['id'] != after['id']: raise RuntimeError('飞机ID排序改变')
                    if after['state'] == 'FLYING' and (before['state'] != 'FLYING' or before['passengers'] != after['passengers']):
                        departures.append(dict(time=int(env.scenario.time), aircraft=after['id'], origin=before['at'], target=after['target'],
                                               passengers=after['passengers']))
                ticks += 1
                if ticks == 1:
                    first_post = d.object_sha(d.state_view(env)); first_air_post = object_sha(after_planes)
                    first_details = detail
                if ticks in (1, 5, 15, 30, 60, 120, 240) or done or env.scenario.time >= end_time:
                    points[str(ticks)] = dict(total=total, operating=operating, tail=tail)
                    air_points[str(ticks)] = object_sha(after_planes)
                if done: break
        if not ticks: raise RuntimeError('空回放')
        # 最后一个时刻只补记录状态，不能重复积累一分钟人时。
        final_s = env.scenario
        for pid, p in final_s.persons.persons.items():
            pid = str(pid)
            row = timeline.setdefault(pid, dict(born=int(p.spawn_time), queue_seen=None, board_seen=None, finish_seen=None, station=None))
            if str(pid) in set(map(str, final_s.finished_ids)) and row['finish_seen'] is None: row['finish_seen'] = int(final_s.time)
            if p.sub_state == 'fly' and row['board_seen'] is None: row['board_seen'] = int(final_s.time)
        last = points[str(ticks)]
        for horizon in (1, 5, 15, 30, 60, 120, 240):
            if str(horizon) not in points: points[str(horizon)] = dict(last, boundary_clipped=True)
        if sum(phases.values()) != total or sum(cohorts.values()) != total or sum(individual.values()) != total:
            raise RuntimeError('分支人时守恒失败')
        job['_counters']['branch_calls'] += 1
        job['_counters']['simulated_minutes'] += ticks
        return dict(plan=plan, total=total, operating=operating, tail=tail, nonabsorbing=total-tail,
            phases=dict(phases), cohorts=dict(cohorts), individual=dict(individual), timeline=timeline,
            departures=departures, remaining=len(set(final_s.persons.persons)-set(final_s.finished_ids)),
            generated=len(final_s.persons.persons), start=start, end=int(final_s.time), ticks=ticks,
            first_post=first_post, first_air_post=first_air_post, first_details=first_details,
            points=points, cost_curve=cost_curve, air_points=air_points, second=b_record, focal=focal,
            privileged_labels=forecast is None, new_training_transitions=0)
    finally: env.close()


def action_plans(d, base, m, job, private, snapshot, model, norm, controller):
    env, obs, rng = snapshot['env'], snapshot['obs'], snapshot['rng']
    d.rng_set(m, rng)
    probe = base.clone_env(env)
    try:
        _, _, original = advance(d, base, m, job, private, probe, obs.copy(), model, norm, controller)
        expected = d.object_sha(d.state_view(probe))
    finally: probe.close()
    plans = [dict(p=original['passenger'])]
    choices = list(range(env.k)) if original['active'] else [0]
    for p in choices:
        candidate = dict(p=p)
        if candidate not in plans: plans.append(candidate)
        if env.joint:
            d.rng_set(m, rng); probe = base.clone_env(env)
            try:
                _, _, detail = advance(d, base, m, job, private, probe, obs.copy(), model, norm, controller, force_p=p)
                for air in detail['legal']:
                    if air != detail['aircraft'] and dict(p=p, air=air) not in plans: plans.append(dict(p=p, air=air))
            finally: probe.close()
    d.rng_set(m, rng)
    return plans, original, expected


def quality_record(rows, original, epsilon):
    best = min(range(len(rows)), key=lambda i: (rows[i]['total'], i != 0, i))
    ref, winner = rows[0], rows[best]
    gain = ref['total']-winner['total']
    passenger = [row for row in rows if 'air' not in row['plan']]
    aircraft = [row for row in rows if row['plan']['p'] == original['passenger']]
    phase_gain = {key: ref['phases'].get(key, 0)-winner['phases'].get(key, 0) for key in ('ground', 'wait', 'flight', 'other')}
    if abs(sum(phase_gain.values())-gain) > 1e-8: raise RuntimeError('收益分解不守恒')
    return dict(winner=best, gain=gain, near_best=gain <= epsilon,
        candidate_span=max(row['total'] for row in rows)-min(row['total'] for row in rows),
        operating_gain=ref['operating']-winner['operating'], nonabsorbing_gain=ref['nonabsorbing']-winner['nonabsorbing'],
        tail_gain=ref['tail']-winner['tail'], phase_gain=phase_gain,
        cohort_gain={key: ref['cohorts'].get(key, 0)-winner['cohorts'].get(key, 0) for key in ('focal', 'existing', 'future')},
        passenger_only_gain=ref['total']-min(row['total'] for row in passenger),
        aircraft_only_gain=ref['total']-min(row['total'] for row in aircraft),
        unique_first_physical_states=len({row['first_post'] for row in rows}),
        unique_first_air_states=len({row['first_air_post'] for row in aircraft}),
        short_full_flip={str(h): not bool(
            {i for i, row in enumerate(rows) if row['points'][str(h)]['total'] == min(r['points'][str(h)]['total'] for r in rows)}
            & {i for i, row in enumerate(rows) if row['total'] == winner['total']}) for h in (5, 30, 60, 120)},
        reference_remaining=ref['remaining'], winner_remaining=winner['remaining'],
        service_change=service_change(ref, winner))


def service_change(reference, winner):
    """把总收益落到具体乘客；服务轮次只作已观测顺序标签，不冒称存在空位可直接搭乘。"""
    advanced=[]; delayed=[]; censored=[]
    people=set(reference.get('timeline',{}))|set(winner.get('timeline',{}))
    for pid in sorted(people):
        a=reference.get('timeline',{}).get(pid,{});b=winner.get('timeline',{}).get(pid,{})
        ta,tb=a.get('board_seen'),b.get('board_seen')
        if ta is None or tb is None:
            censored.append(pid);continue
        if ta==tb:continue
        same=a.get('station')==b.get('station')
        between=sum(bool(e['passengers']) and str(e.get('origin'))==a.get('station') and min(ta,tb)<=e['time']<max(ta,tb)
                    for e in reference.get('departures',[])) if same else None
        row=dict(id=pid,reference_board=ta,winner_board=tb,minutes_earlier=ta-tb,same_station=same,
            observed_departures_between=between,
            net_person_minutes=reference.get('individual',{}).get(pid,0)-winner.get('individual',{}).get(pid,0))
        (advanced if tb<ta else delayed).append(row)
    return dict(advanced_count=len(advanced),delayed_count=len(delayed),board_censored_count=len(censored),
        same_station_advanced_past_observed_service=sum(r['same_station'] and (r['observed_departures_between'] or 0)>0 for r in advanced),
        advanced=advanced,delayed=delayed,
        note='数的是观测到的服务顺序，不证明原来那班存在空位；所有乘客净人时另行守恒核对。')


def delay_record(rows, scores, original, epsilon):
    if scores is None: return dict(status='NO_PASSENGER_DECISION')
    # 只改乘客动作时，飞机侧仍执行原控制规则；不把飞机同时更改的收益算作延迟利用。
    values = {row['plan']['p']: row for row in rows if 'air' not in row['plan']}
    costs = {key: row['total'] for key, row in values.items()}
    best = min(costs.values())
    now = min(range(len(scores)), key=lambda i: (scores[i]['current_score'], i))
    ready = min(range(len(scores)), key=lambda i: (scores[i]['ready_score'], i))
    choices = []
    for p, row in sorted(values.items()):
        chain = row['timeline'].get(row['focal'], {})
        choices.append(dict(p=p, cost=row['total'], conditional_loss=row['total']-best,
            estimated_access=scores[p]['access'], queue_seen=chain.get('queue_seen'), board_seen=chain.get('board_seen'),
            queue_delay=chain['queue_seen']-row['start'] if chain.get('queue_seen') is not None else None,
            board_delay=chain['board_seen']-row['start'] if chain.get('board_seen') is not None else None,
            censored_queue=chain.get('queue_seen') is None, censored_board=chain.get('board_seen') is None))
    effect=None
    boundaries=[choice['queue_seen'] if choice['queue_seen'] is not None else choice['board_seen'] for choice in choices]
    if all(value is not None for value in boundaries) and all('cost_curve' in row for row in values.values()):
        boundary=max(boundaries)-rows[0]['start']
        picked=values[original['passenger']]
        winner=values[min(costs,key=lambda p:(costs[p],p!=original['passenger'],p))]
        def prefix(row):return row['cost_curve'][min(max(0,boundary),len(row['cost_curve'])-1)]
        before=prefix(picked)-prefix(winner)
        effect=dict(common_minutes=boundary,loss_before_common_entry_bound=before,
                    loss_after_common_entry_bound=costs[original['passenger']]-best-before,
                    boundary_note='统一绝对时间边界；没观测到入队但观测到登机时，仅以登机作入队上界，不补造真实入队时刻。')
    return dict(status='COMPLETE', scores=scores, choices=choices,
        current_choice=now, ready_choice=ready, proxies_disagree=now != ready,
        policy_choice=original['passenger'], policy_loss=costs[original['passenger']]-best,
        policy_action_probabilities=original.get('passenger_probs'),
        probability_mass_on_near_best=sum(prob for p,prob in enumerate(original['passenger_probs']) if costs[p]<=best+epsilon)
            if original.get('passenger_probs') is not None else None,
        high_confidence_wrong=bool(original.get('passenger_probs') is not None
            and max(original['passenger_probs'])>=.8 and costs[original['passenger']]-best>epsilon),
        current_proxy_loss=costs[now]-best, ready_proxy_loss=costs[ready]-best,
        access_spread=max(s['access'] for s in scores)-min(s['access'] for s in scores),
        policy_near_best=costs[original['passenger']]-best <= epsilon,
        delayed_effect_comparison=effect,
        interpretation='只检验实际选择是否正确利用延迟；策略动作概率不是正确性的置信度，不能据此证明网络内部表征或PPO原理上学不会。')


def cross_time(d, base, m, job, private, snapshot, model, norm, controller, original, reference):
    if not snapshot['env'].joint or not original['active']: return []
    env = snapshot['env']; k = env.k
    alternatives = [p for p in range(k) if p != original['passenger']]
    targets = [(snapshot['slot']+j) % k for j in (0, 1)]
    results = []
    for p in alternatives:
        for target in targets:
            for delay in (1, 10):
                paths = {}
                for a, b in ((0, 0), (1, 0), (0, 1), (1, 1)):
                    plan = dict(p=p if a else original['passenger'])
                    if b: plan.update(second_air=target, second_delay=delay)
                    paths[str(a)+str(b)] = rollout(d, base, m, job, private, env, snapshot['obs'], model, norm,
                                                 controller, snapshot['rng'], plan)
                if paths['00']['total'] != reference['total'] or paths['00']['first_post'] != reference['first_post']:
                    raise RuntimeError('跨时刻四臂参考不复现')
                b0, b1 = paths['01']['second'], paths['11']['second']
                clean_pair = b0['triggered'] and b1['triggered'] and b0['changed'] and b1['changed'] and b0['time'] == b1['time']
                result = causal_four({key: value['total'] for key, value in paths.items()}, clean_pair, job['epsilon'])
                result.update(causal_four_operating=causal_four({key: value['operating'] for key, value in paths.items()}, clean_pair, job['epsilon']),
                    p=p, target=target, requested_delay=delay, second_reference=b0, second_changed_a=b1,
                    opportunity_shift=b0['time'] != b1['time'], costs={key: value['total'] for key, value in paths.items()},
                    nonabsorbing_costs={key: value['nonabsorbing'] for key, value in paths.items()},
                    phase_costs={key: value['phases'] for key, value in paths.items()},
                    service_change=service_change(paths['00'],paths['11']),
                    remaining={key: value['remaining'] for key, value in paths.items()},
                    note='B是下一真实合法调机机会的反馈干预；触发时间不同单列，不能冒充固定同一事件的纯交互。')
                results.append(result)
    return results


def compress_row(row):
    # 保留逐乘客首次入队/登机和有符号个体成本，便于人工查证具体哪一批得失。
    return row


def diagnose_snapshot(d, base, m, job, private, snapshot, model, norm, baseline):
    target = Path(job['out']) / ('state_%02d.json' % snapshot['slot'])
    if target.exists(): return
    env = snapshot['env']; before = d.object_sha(d.state_view(env))
    controller = job['case']['controller']; origin=job.get('origin','own')
    follow='READY' if origin=='common_ready' else controller
    plans, original, expected = action_plans(d, base, m, job, private, snapshot, model, norm, controller)
    rows = [rollout(d, base, m, job, private, env, snapshot['obs'], model, norm, follow, snapshot['rng'], plan,
                    initial_controller=controller) for plan in plans]
    offset = snapshot['offset']
    if rows[0]['first_post'] != expected:
        raise RuntimeError('克隆参考首步不等于原动作首步')
    common_reference=None
    if origin=='common_ready':
        ready_plan=dict(p=int(base.ready(env,m)))
        if env.joint:ready_plan['air']=-1
        common_reference=rollout(d,base,m,job,private,env,snapshot['obs'],model,norm,'READY',snapshot['rng'],ready_plan)
        verified_cost=common_reference['total']
    else:verified_cost=rows[0]['total']
    if verified_cost != sum(baseline['ledger'][offset:]):
        raise RuntimeError('克隆参考不等于原轨迹，停止该状态，不发布伪归因')
    quality = quality_record(rows, original, job['epsilon'])
    delay = delay_record(rows, heuristic_scores(env, m), original, job['epsilon'])
    alternative = None
    # 每五个槽固定补一个不同后续策略，排查错误是否依赖原策略的后续补救；不按收益挑状态。
    if origin=='own' and snapshot['slot'] % 5 == 0 and controller != 'READY':
        others = [rollout(d, base, m, job, private, env, snapshot['obs'], model, norm, 'READY', snapshot['rng'], plan,
                         initial_controller=controller) for plan in plans]
        if others[0]['first_post'] != expected: raise RuntimeError('更换后续策略时不得偷换首次原动作')
        alternative = dict(continuation='READY', quality=quality_record(others, original, job['epsilon']),
                           rows=[compress_row(row) for row in others])
    sequences = []
    if origin=='own' and snapshot['kind'] == 'passenger' and snapshot['slot'] % 5 == 0:
        sequences = cross_time(d, base, m, job, private, snapshot, model, norm, controller, original, rows[0])
    if d.object_sha(d.state_view(env)) != before: raise RuntimeError('分支污染模板状态')
    save(target, dict(case=job['case']['case'], bank=job['bank']['name'], slot=snapshot['slot'], kind=snapshot['kind'],
        time=snapshot['time'], state_sha=before, origin=origin, original=original, quality=quality, delay=delay,
        public_state=d.state_view(env),raw_observation=snapshot['obs'].tolist(),
        ready_reference_cost=common_reference['total'] if common_reference is not None else None,
        model_first_choice_vs_ready_gain=common_reference['total']-rows[0]['total'] if common_reference is not None else None,
        rows=[compress_row(row) for row in rows], alternate_continuation=alternative, sequences=sequences,
        clone_reference_passed=True, sample_not_selected_by_loss=True, oracle_labels_only=True, new_training_transitions=0))
    save(Path(job['out']) / 'LIVE.json', dict(last_slot=snapshot['slot'], counters=job['_counters'], time=time.time()))


def collect(d, base, m, job, private, model, norm):
    env, obs = base.env_new(m, private, job['bank']['path'], 123)
    origin=job.get('origin','own')
    controller = 'READY' if origin=='common_ready' else job['case']['controller']
    reservoirs = defaultdict(list); seen = Counter()
    ledger = []; events = []; counts = [0]*env.k
    try:
        with m.torch.no_grad():
            while True:
                guard(job)
                active = bool(env.scenario.waiting_decisions)
                probe = None
                if active: sample_snapshot(d, base, m, job, env, obs, reservoirs, seen, 'passenger', len(ledger))
                elif env.joint and 40 <= env.scenario.time < 260:
                    rng = d.rng_get(m); probe = base.clone_env(env)
                    try:
                        _, _, detail = advance(d, base, m, job, private, probe, obs.copy(), model, norm, controller)
                        d.rng_set(m, rng)
                        if len(detail['legal']) > 1: sample_snapshot(d, base, m, job, env, obs, reservoirs, seen, 'air_only', len(ledger))
                    finally: probe.close(); d.rng_set(m, rng)
                n, _, _ = d.cost_tick(env, set(), None); ledger.append(n)
                # 整场记录完整时序链，候选分支仍只在预定正常阶段抽样。
                pre = d.state_view(env)
                obs, done, detail = advance(d, base, m, job, private, env, obs, model, norm, controller)
                post = d.state_view(env)
                events.append(dict(time=pre['time'], active=active, action=detail,
                                   pre_planes=pre['planes'], post_planes=post['planes']))
                if active: counts[detail['passenger']] += 1
                if done: break
        metrics = base.metrics(m, private, env, counts, sum(ledger))
        if controller == 'MODEL':
            path = Path(job['source']) / 'cells' / job['case']['case'] / 'evaluation' / ('step_%09d.json' % d.FINAL_STEP)
            records = [r for r in read(path)['episodes'] if r['trace'] == job['bank']['name'] and r['eval_seed'] == 123]
            if len(records) != 1 or abs(records[0]['restricted_person_time_per_generated']-metrics['restricted_person_time_per_generated']) > 1e-7:
                raise RuntimeError('输入最终模型未复现其原评估；禁止换模型凑数')
        job['_counters']['full_episodes'] += 1; job['_counters']['simulated_minutes'] += len(ledger)
        chosen = {}; coverage = []
        for band in range(5):
            if env.joint:
                layout = [(kind, idx) for kind, idx in [('passenger', 0), ('passenger', 1), ('air_only', 0),
                    ('passenger', 2), ('passenger', 3), ('air_only', 1)]]
            else: layout = [('passenger', i) for i in range(6)]
            for within, (kind, index) in enumerate(layout):
                pool = sorted(reservoirs[(kind, band)], key=lambda r: (r['time'], r['offset']))
                slot = band*6+within
                exists = index < len(pool)
                coverage.append(dict(slot=slot, kind=kind, band=band, eligible_seen=seen[(kind, band)], sampled=exists))
                if exists: chosen[slot] = dict(pool[index], slot=slot)
        baseline = dict(metrics=metrics, ledger=ledger, events=events, coverage=coverage,
            note='同一格的多次基准只做确定性核对，不重复计成独立样本。')
        reference = Path(job['root_out']) / ('common_baselines' if origin=='common_ready' else 'baselines') / job['case']['case'] / (job['bank']['name']+'.json')
        if reference.exists():
            prior = read(reference)
            if prior['ledger'] != ledger or prior['coverage'] != coverage: raise RuntimeError('分层抽样或基准跨批次不复现')
        else: save(reference, baseline)
        return baseline, chosen
    except BaseException:
        for pool in reservoirs.values():
            for item in pool: item['env'].close()
        raise
    finally: env.close()


def public_worlds(d, env, draws):
    history = d.public_history(env)
    worlds = [d.forecast_world(history, 73100+i, 120) for i in range(draws)]
    return history, worlds


def choose_mean(costs, reference=0):
    means = [statistics.mean(row) for row in costs]
    return min(range(len(means)), key=lambda i: (means[i], i != reference, i))


def online_episode(d, base, m, job, private, model, norm):
    """最多两次合法滚动选择，用真实后续核对；这是简单规划对照，不是新方法。"""
    env, obs = base.env_new(m, private, job['bank']['path'], 123)
    controller = job['case']['controller']; area = 0; counts = [0]*env.k; decisions = []; gates = [80, 180]
    pending_plan = None; episode_ticks = 0
    try:
        with m.torch.no_grad():
            while True:
                guard(job)
                n, _, _ = d.cost_tick(env, set(), None); area += n
                forced = None
                if gates and env.scenario.time >= gates[0] and env.scenario.waiting_decisions:
                    gate = gates.pop(0); state_rng = d.rng_get(m)
                    temp = dict(env=env, obs=obs, rng=state_rng)
                    plans, original, expected = action_plans(d, base, m, job, private, temp, model, norm, controller)
                    # 小宽度两步候选：当前乘客选站，随后真实合法机会的目标；不偷看实际未来选动作。
                    choices = [dict(p=original['passenger'])]
                    for p in range(env.k):
                        if dict(p=p) not in choices: choices.append(dict(p=p))
                        if env.joint:
                            for target in range(env.k): choices.append(dict(p=p, second_air=target, second_delay=1))
                    history, worlds = public_worlds(d, env, 8)
                    if any(world is None for world in worlds):
                        decisions.append(dict(gate=gate, time=int(env.scenario.time), status='INSUFFICIENT_HISTORY'))
                    else:
                        costs = [[rollout(d, base, m, job, private, env, obs, model, norm, controller, state_rng,
                            plan, forecast=world, end_time=min(END_TIME, int(env.scenario.time)+120))['total']
                            for world in worlds] for plan in choices]
                        pick = choose_mean(costs); left = choose_mean([r[:4] for r in costs]); right = choose_mean([r[4:] for r in costs])
                        forced = choices[pick]
                        decisions.append(dict(gate=gate, time=int(env.scenario.time), status='COMPLETE', choice=forced,
                            half_draws_agree=left == right, costs=costs, history_sha=object_sha(history),
                            worlds_sha=[object_sha(w) for w in worlds], no_actual_future_used=True))
                    d.rng_set(m, state_rng)
                # 预测选出的第二步在未来实际合法机会执行，不能把模拟里的事件时间当真值。
                if forced is not None:
                    pending_plan = dict(forced, start=int(env.scenario.time), used=False)
                def hook(now, legal, natural):
                    if not pending_plan or pending_plan.get('second_air') is None or pending_plan['used']: return None
                    if pending_plan['start']+1 <= now <= pending_plan['start']+11 and len(legal)>1 and pending_plan['second_air'] in legal:
                        pending_plan['used'] = True
                        return pending_plan['second_air']
                    return None
                active = bool(env.scenario.waiting_decisions)
                obs, done, detail = advance(d, base, m, job, private, env, obs, model, norm, controller,
                    force_p=forced['p'] if forced is not None else None, hook=hook if forced is None else None)
                episode_ticks += 1
                if active: counts[detail['passenger']] += 1
                if done: break
        metrics = base.metrics(m, private, env, counts, area)
        job['_counters']['full_episodes'] += 1
        job['_counters']['simulated_minutes'] += episode_ticks
        save(Path(job['out'])/'ONLINE.json', dict(metrics=metrics, decisions=decisions,
            actual_future_policy_input=False, new_training_transitions=0,
            note='固定80/180分钟后的首个乘客机会，最多两次；8个经验世界，不是已证明最优MPC。'))
    finally: env.close()


def worker(path):
    job = read(path); job['_counters'] = dict(branch_calls=0, full_episodes=0, simulated_minutes=0)
    started = time.monotonic(); d = adapter(); d.check = guard
    base, m, model, norm, private = d.runtime(job)
    before_policy, before_norm = m.policy_sha(model.policy), d.norm_sha(norm)
    snapshots = {}
    try:
        if job['phase'] == 'online': online_episode(d, base, m, job, private, model, norm)
        else:
            baseline, snapshots = collect(d, base, m, job, private, model, norm)
            selected=pass_slots(job['case']['task']['control'],job['pass_id']) if job.get('origin','own')=='own' else [
                normal_slots(job['case']['task']['control'])[i] for i in ((0,26) if job['case']['task']['control']=='J3' else (0,25))]
            for _, slot in selected:
                if slot not in snapshots:
                    save(Path(job['out'])/('MISSING_%02d.json' % slot), dict(slot=slot, reason='该分层没有足够真实合法机会，未补造或挑坏状态'))
                    continue
                diagnose_snapshot(d, base, m, job, private, snapshots[slot], model, norm, baseline)
        if before_policy != m.policy_sha(model.policy) or before_norm != d.norm_sha(norm):
            raise RuntimeError('模型或归一化统计更新，拒绝发布结果')
        save(Path(job['out'])/'END.json', dict(status='COMPLETE', weights_unchanged=True, norm_unchanged=True,
            counters=job['_counters'], wall_seconds=time.monotonic()-started, new_training_transitions=0))
    finally:
        for value in snapshots.values(): value['env'].close()
        save(Path(job['out'])/('COUNTERS_%d.json' % time.time_ns()),
             dict(job['_counters'], wall_seconds=time.monotonic()-started))


def cases_and_bank(d, source):
    values, plan = d.locate_cases(source)
    models = [c for c in values if c['controller']=='MODEL' and c['task']['gamma']==.99]
    if len(models) != 16: raise RuntimeError('需要16个普通模型，不按成绩挑模型')
    ready = []
    for control in ('J3', 'LQ'):
        c = copy.deepcopy(next(c for c in models if c['task']['control']==control))
        c.update(case='READY_'+control, controller='READY', training_seed=None)
        ready.append(c)
    # 同一seed的控制/网络轮转，避免预算不足时只剩一种算法。
    models.sort(key=lambda c: (c['training_seed'], c['task']['network'], c['task']['control']))
    values = ready+models
    return values, d.locate_bank(source, plan)


def launch(job, retry):
    out = Path(job['out']); out.mkdir(parents=True, exist_ok=True)
    if (out/'END.json').exists(): return dict(status='EXISTING', case=job['case']['case'], phase=job['phase'])
    if (out/'FAILED.json').exists() and not retry: return dict(status='FAILED_PRESERVED', case=job['case']['case'], phase=job['phase'])
    if time.monotonic() >= job['deadline']-10: return dict(status='BUDGET_SKIPPED', case=job['case']['case'], phase=job['phase'])
    save(out/'JOB.json', job)
    started = time.monotonic()
    if job['phase']=='online' and not (Path(job['root_out'])/'baselines'/job['case']['case']/(job['bank']['name']+'.json')).is_file():
        return dict(status='FAILED',case=job['case']['case'],phase=job['phase'],error='同格基准未通过，不发布在线对照')
    with (out/'worker.log').open('a', encoding='utf-8') as log:
        process = subprocess.Popen([sys.executable, '-B', '-u', str(Path(__file__).resolve()), '--worker', str(out/'JOB.json')],
                                   cwd=PROJECT, stdout=log, stderr=subprocess.STDOUT)
        while process.poll() is None:
            if time.monotonic() >= job['deadline']+2 or (Path(job['run_root'])/'STOP_REQUESTED').exists():
                process.terminate()
                try: process.wait(timeout=5)
                except subprocess.TimeoutExpired: process.kill(); process.wait()
                live=read(out/'LIVE.json') if (out/'LIVE.json').exists() else {}
                save(out/('TERMINATED_%d.json'%time.time_ns()),dict(last_completed_counters=live.get('counters',{}),
                    wall_seconds=time.monotonic()-started,note='硬停止时未完成分支耗时可能未计入，不填造完整计数'))
                return dict(status='BUDGET_PARTIAL', case=job['case']['case'], phase=job['phase'])
            time.sleep(.5)
    if process.returncode == 0 and (out/'END.json').exists(): status='COMPLETE'
    elif process.returncode == 130: status='BUDGET_PARTIAL'
    else:
        status='FAILED'
        failure=dict(status=status, exit_code=process.returncode, log=str(out/'worker.log'), time=time.time())
        save(out/('FAILED_%d.json' % time.time_ns()), failure)
        if not (out/'FAILED.json').exists(): save(out/'FAILED.json', failure)
    return dict(status=status, case=job['case']['case'], phase=job['phase'], seconds=time.monotonic()-started)


def write_csv(path, rows):
    fields = list(dict.fromkeys(key for row in rows for key in row))
    with Path(path).open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=fields); writer.writeheader()
        writer.writerows({k: json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else v for k, v in row.items()} for row in rows)


def summarize(out, cases):
    delays=[]; controls=[]; sequences=[]; episodes=[]; online=[]; missing=[]; unique=set(); physical_unique=set(); counters=Counter(); common_hashes=defaultdict(set)
    by_case={c['case']:c for c in cases}
    for path in sorted((out/'baselines').glob('*/*.json')):
        result=read(path); name=path.parent.name
        episodes.append(dict(case=name, bank=path.stem, **result['metrics']))
    for path in sorted((out/'jobs').glob('*/*/*/state_*.json')):
        result=read(path); key=(result['case'],result['bank'],result.get('origin','own'),result['slot'])
        if key in unique: raise RuntimeError('同一格的槽位被重复汇总')
        unique.add(key); physical_unique.add((result['bank'],result['state_sha'])); c=by_case[result['case']]
        meta=dict(case=result['case'],bank=result['bank'],slot=result['slot'],kind=result['kind'],time=result['time'],
            control=c['task']['control'],network=c['task']['network'] if c['controller']=='MODEL' else 'RULE',
            training_seed=c['training_seed'],controller=c['controller'],origin=result.get('origin','own'))
        if meta['origin']=='common_ready':common_hashes[(meta['control'],meta['bank'],meta['slot'])].add(result['state_sha'])
        controls.append(dict(meta,**result['quality'],model_first_choice_vs_ready_gain=result.get('model_first_choice_vs_ready_gain'),
            alternate_continuation=result['alternate_continuation']['quality'] if result['alternate_continuation'] else None))
        if result['delay']['status']=='COMPLETE': delays.append(dict(meta,**result['delay']))
        for row in result['sequences']: sequences.append(dict(meta,**row))
    for path in sorted((out/'jobs').glob('*/*/*/ONLINE.json')):
        item=read(path); name=path.parent.parent.name; bank=path.parent.name
        reference=read(out/'baselines'/name/(bank+'.json'))['metrics']
        online.append(dict(case=name,bank=bank,baseline_rpt=reference['restricted_person_time_per_generated'],
            online_rpt=item['metrics']['restricted_person_time_per_generated'],
            gain_rpt=reference['restricted_person_time_per_generated']-item['metrics']['restricted_person_time_per_generated'],
            baseline_completion=reference['completion'],online_completion=item['metrics']['completion'],
            decisions=item['decisions']))
    for path in (out/'jobs').glob('*/*/*/MISSING_*.json'): missing.append(dict(path=str(path.relative_to(out)),**read(path)))
    if any(len(values)>1 for values in common_hashes.values()):raise RuntimeError('共同READY状态物理hash不一致，不发布跨模型共同状态对照')
    for path in (out/'jobs').glob('*/*/*/COUNTERS_*.json'):
        for key,value in read(path).items():
            if key in ('branch_calls','full_episodes','simulated_minutes','wall_seconds') and isinstance(value,(int,float)): counters[key]+=value
    for name,rows in [('01_整场基准.csv',episodes),('02_延迟利用与候选排序.csv',delays),('03_动作控制效果.csv',controls),
                      ('04_跨时刻四臂配合.csv',sequences),('05_合法滚动规划整场.csv',online),('06_机会不足未补造.csv',missing)]: write_csv(out/name,rows)
    groups=defaultdict(list)
    for row in controls: groups[(row['case'],row['origin'])].append(row)
    model_rows=[]
    for (case,origin),rows in groups.items():
        ds=[r for r in delays if r['case']==case and r['origin']==origin]; pairs=[r for r in sequences if r['case']==case and r['origin']==origin]
        model_rows.append(dict(case=case,origin=origin,states=len(rows),pax_states=len(ds),air_only=sum(r['kind']=='air_only' for r in rows),
            mean_conditional_loss=statistics.mean(r['gain'] for r in rows),
            policy_delay_loss=statistics.mean(r['policy_loss'] for r in ds) if ds else None,
            proxy_disagreements=sum(r['proxies_disagree'] for r in ds),
            clean_sequence_pairs=sum(r['clean_pair'] for r in pairs),pair_required=sum(r['pair_required'] for r in pairs),
            note='本模型内摘要；状态不是独立训练种子；抽样损失不相加解释整场差距。'))
    write_csv(out/'07_逐模型先读摘要.csv',model_rows)
    rules=[
        ('延迟长但策略排序依然正确','不再用时间错配作为主假说，不扩时间特征。'),
        ('延迟相关排序错误在多个种子重复，READY也存在','先查具体失误对应哪个实际服务机会；只有离线空间还不够启动新算法。'),
        ('只有模型差，READY不差','优先研究如何稳定学到已知规则能力，不宣称交通领域共同缺口。'),
        ('多个合法飞机动作实际无效果','首先审查权限和执行契约；给所有基线同样修正，不把修bug当创新。'),
        ('两次单改无益，配合修改有正常阶段净收益','保留跨时刻协同候选；先用合法小规划检验可在线利用性，再设计有针对性的训练。'),
        ('成对收益只来自少数状态、尾部或触发时刻变化','不作为主要协同证据，避免强行给MARL找理由。'),
        ('简单合法滚动规划稳定改善','将其保留为强基线；学习的任务是降低同等效果的计算成本或改善剩余具体错误。'),
        ('事后有空间、合法预测却不稳定','先查预测抽样和排序误差；不能把事后最优当在线效果，更不能立即上千万训练。')]
    save(out/'后续训练分支.json',dict(automatic_training=False,new_training_transitions=0,rules=rules,
        not_identifiable_without_training=['移除延迟特征后重新训练的因果效果','新MARL/新网络是否能学会并稳定优于普通基线',
            '阶段反馈或信用分配训练修正的真正作用','普通PPO的理论表达能力极限']))
    summary=dict(completed_state_slots=len(unique),unique_physical_states=len(physical_unique),delay_states=len(delays),sequence_comparisons=len(sequences),online_episodes=len(online),
        missing_opportunity_slots=len(missing),counters=dict(counters),new_training_transitions=0,
        planned_state_slots=1144,own_state_slots=1080,common_control_slots=64,scale_reference_states=104,scale_target_ratio=1144/104,
        common_ready_hash_check=True,
        independent_units='模型训练种子；同一模型多状态和多验证顺序为重复测量；READY不是多种子。')
    save(out/'规模与耗时.json',summary)
    body='<h1>一小时冻结模型诊断</h1><p>这是为后续训练筛选具体问题的实验，不自动宣称找到创新。</p>'
    body+='<p>先读07逐模型摘要；02查延迟，03查控制效果，04查跨时刻配合，05查合法简单规划。完整逐乘客记录在jobs。</p>'
    body+='<pre>'+html.escape(json.dumps(summary,ensure_ascii=False,indent=2))+'</pre><h2>下一步按结果走</h2><ul>'
    body+=''.join('<li>'+html.escape(a+'：'+b)+'</li>' for a,b in rules)+'</ul>'
    body+='<h2>每个模型先看这几列</h2><p>损失越低，表示在本次已枚举候选里原选择越接近较好选择；不是理论全局最优差距。</p>'
    body+='<table><tr><th>模型</th><th>状态数</th><th>延迟相关选择损失均值</th><th>无乘客调机状态</th><th>共同合法配对数</th><th>其中需配合案例</th></tr>'
    for row in model_rows:
        value='未测' if row['policy_delay_loss'] is None else '%.1f人·分钟'%row['policy_delay_loss']
        body+='<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in (row['case']+' / '+row['origin'],row['states'],value,row['air_only'],row['clean_sequence_pairs'],row['pair_required']))+'</tr>'
    body+='</table><h2>合法小规划有没有整场帮助</h2><p>正数表示减少固定截止人时/人，负数表示反而更差；两个验证顺序不是两个训练种子。</p>'
    body+='<table><tr><th>模型</th><th>验证顺序</th><th>人时/人净改善</th><th>原完成率</th><th>规划后完成率</th></tr>'
    for row in online:
        body+='<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in (row['case'],row['bank'],round(row['gain_rpt'],3),row['baseline_completion'],row['online_completion']))+'</tr>'
    body+='</table>'
    body+='<p>未完成全体乘客的ATT仍为NaN；人时与完成率单列。真实未来仅作离线标签，不进入在线动作选择。</p>'
    (out/'诊断报告.html').write_text('<!doctype html><meta charset="utf-8"><style>body{max-width:1150px;margin:40px auto;padding:0 20px;font:17px/1.8 sans-serif}li{margin:12px}pre{white-space:pre-wrap}table{border-collapse:collapse;font-size:14px}td,th{padding:8px;border:1px solid #cbd5e1;overflow-wrap:anywhere}</style>'+body,encoding='utf-8')
    return summary


def pack(out):
    target=out/(out.name+'_DATAONLY.tar.gz'); pending=target.with_suffix('.pending')
    with tarfile.open(pending,'w:gz',compresslevel=5) as archive:
        for path in sorted(out.rglob('*')):
            relative=path.relative_to(out)
            if path.is_file() and not path.is_symlink() and 'work' not in relative.parts and path.suffix in ('.json','.csv','.log','.md','.html'):
                archive.add(path,arcname=out.name+'/'+relative.as_posix(),recursive=False)
        archive.add(Path(__file__).resolve(),arcname=out.name+'/ENTRYPOINT.py',recursive=False)
    os.replace(pending,target)
    print('[诊断数据包]',target,flush=True)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source',type=Path,default=PROJECT/'serial_runs'/SOURCE_NAME)
    parser.add_argument('--out',type=Path,default=PROJECT/'workspace/artifacts/uam_mechanisms_1h_20261103_v1')
    parser.add_argument('--wall-seconds',type=int,default=3600)
    parser.add_argument('--workers',type=int,choices=(1,2),default=2)
    parser.add_argument('--epsilon',type=float,default=10.)
    parser.add_argument('--resume',action='store_true');parser.add_argument('--retry-failed',action='store_true')
    parser.add_argument('--pack-only',action='store_true');parser.add_argument('--plan',action='store_true');parser.add_argument('--worker')
    args=parser.parse_args()
    if args.plan:
        print(json.dumps(dict(version=VERSION,model_controllers=16,rule_controllers=2,validation_traces=2,
            target_state_slots=1144,own_states=1080,common_ready_control_slots=64,previous_unique_states=104,previous_branch_calls=1060,
            target_branch_calls='约8000至12000，取决于真实合法候选及机会数量',workers=args.workers,
            wall_seconds=args.wall_seconds,no_training=True,source=SOURCE_NAME),ensure_ascii=False,indent=2));return
    if args.worker:
        try:worker(args.worker)
        except TimeoutError:raise SystemExit(130)
        except BaseException:
            traceback.print_exc();raise
        return
    source,out=args.source.resolve(),args.out.resolve()
    if not 120 <= args.wall_seconds <= 3600 or args.epsilon < 0:raise RuntimeError('单会话上限一小时，容差非负')
    if source!=(PROJECT/'serial_runs'/SOURCE_NAME).resolve() or args.source.is_symlink():raise RuntimeError('只读取指定已完成训练目录')
    if out.parent!=(PROJECT/'workspace/artifacts').resolve() or not out.is_relative_to(PROJECT.resolve()) or not out.name.startswith('uam_mechanisms_1h_') or args.out.is_symlink():
        raise RuntimeError('输出只能是本项目workspace/artifacts中的本轮独立目录')
    if out.exists() and not args.resume and not args.pack_only:raise RuntimeError('已有结果不覆盖，请使用--resume或另取--out')
    out.mkdir(parents=True,exist_ok=True);d=adapter();lock=d.lock_parent(out);started=time.monotonic()
    try:
        cases,bank=cases_and_bank(d,source)
        contract=dict(version=VERSION,script_sha256=sha(__file__),frozen_adapter_sha256=ADAPTER_SHA,
            source=str(source),cases=cases,bank=bank,epsilon=args.epsilon,seed=SEED,
            source_weights='最终存档，不选Best；16个gamma=.99普通模型，LSTM与Transformer、单侧与联合各4训练种子',
            state_plan='40至260分钟分五层；单侧30乘客，联合20乘客加10无新乘客调机；另加64个共同READY状态对照槽',
            end_time=END_TIME,no_training=True,no_physics_change=True,no_information_addition=True,
            validation='只使用已看过4303/4304，不触碰650x确认顺序',
            approximation='真实未来只作离线条件标签；未知请求经验重采样只来自已揭示历史')
        manifest=out/'MANIFEST.json'
        if manifest.exists():
            if read(manifest)!=contract:raise RuntimeError('代码、模型、需求或科学合同改变，拒绝混入旧结果')
        else:save(manifest,contract)
        if args.pack_only:summarize(out,cases);pack(out);return
        save(out/('RESOURCE_%d.json'%time.time_ns()),d.resource_check(out))
        deadline=started+args.wall_seconds-40;attempts=[]
        # 基础覆盖后先跑合法在线对照，再补深度；不让在线可利用性永远排在最后。
        phases=[('core',0),('common',0),('online',None),('expand1',1),('expand2',2)]
        for phase,pass_id in phases:
            selected=cases if phase!='online' else [c for c in cases if c['case']=='READY_J3' or (
                c['controller']=='MODEL' and c['task']['control']=='J3' and c['task']['network']=='TRANSFORMER')]
            if phase=='common':selected=[c for c in selected if c['controller']=='MODEL']
            jobs=[]
            for c in selected:
                for b in bank:
                    jobs.append(dict(case=c,bank=b,phase=phase,pass_id=pass_id,origin='common_ready' if phase=='common' else 'own',source=str(source),run_root=str(out),
                        root_out=str(out),out=str(out/'jobs'/phase/c['case']/b['name']),
                        work=str(out/'work'/phase/c['case']/b['name']),epsilon=args.epsilon,deadline=deadline))
            with ThreadPoolExecutor(max_workers=args.workers) as pool:
                futures={pool.submit(launch,job,args.retry_failed):job for job in jobs}
                for future in as_completed(futures):
                    try:result=future.result()
                    except Exception as error:result=dict(status='FAILED',error=str(error),case=futures[future]['case']['case'],phase=phase)
                    attempts.append(result);print('[诊断单元]',result,flush=True)
                    save(out/'progress.json',dict(phase=phase,attempts=len(attempts),planned_jobs=PLANNED_JOBS,
                        complete=sum(r['status'] in ('COMPLETE','EXISTING') for r in attempts),
                        failed=sum(r['status'] in ('FAILED','FAILED_PRESERVED') for r in attempts),
                        elapsed_seconds=time.monotonic()-started,last=result,new_training_transitions=0))
            if time.monotonic()>=deadline or (out/'STOP_REQUESTED').exists():break
        summary=summarize(out,cases)
        unchanged=all(sha(c['model'])==c['model_sha'] and sha(c['norm'])==c['norm_sha'] for c in cases)
        if not unchanged:raise RuntimeError('输入模型发生变化，不发布成功结果')
        complete=len(attempts)==PLANNED_JOBS and all(r['status'] in ('COMPLETE','EXISTING') for r in attempts)
        status='COMPLETE' if complete else 'PARTIAL_FAILURE' if any(r['status'] in ('FAILED','FAILED_PRESERVED') for r in attempts) else 'BUDGET_PARTIAL'
        end=dict(status=status,wall_seconds=time.monotonic()-started,results=attempts,weights_unchanged=True,
                 scale=summary,new_training_transitions=0,planned_jobs=PLANNED_JOBS)
        save(out/'SESSION_END.json',end);save(out/'progress.json',dict(phase='complete' if complete else 'stopped',**end));pack(out)
    except BaseException:
        save(out/('PARENT_FAILURE_%d.json'%time.time_ns()),dict(status='FAILED',traceback=traceback.format_exc(),
            new_training_transitions=0,note='原数据未改；完整性异常不能冒充成功，原始记录仍打包便于排查。'))
        try:pack(out)
        except Exception:traceback.print_exc()
        raise
    finally:lock.close()


if __name__=='__main__':main()
